146 |   const roundingMethod = getRoundingMethod(options?.roundingMethod ?? "round");
147 | 
148 |   const milliseconds = earlierDate_.getTime() - laterDate_.getTime();
149 |   const minutes = milliseconds / millisecondsInMinute;
150 | 
151 |   const timezoneOffset =
152 |     readTimezoneOffsetMilliseconds(earlierDate_) -
153 |     readTimezoneOffsetMilliseconds(laterDate_);
