155 |   // Use DST-normalized difference in minutes for years, months and days;
156 |   // use regular difference in minutes for hours, minutes and seconds.
157 |   const dstNormalizedMinutes =
158 |     (milliseconds - timezoneOffset) / millisecondsInMinute;
