169 |     } else if (dstNormalizedMinutes < minutesInMonth) {
170 |       unit = "day";
171 |     } else if (dstNormalizedMinutes < minutesInYear) {
172 |       unit = "month";
173 |     } else {
174 |       unit = "year";
175 |     }
176 |   } else {
177 |     unit = defaultUnit;
178 |   }
179 | 
180 |   // 0 up to 60 seconds
181 |   if (unit === "second") {
182 |     const seconds = roundingMethod(milliseconds / 1000);
183 |     return locale.formatDistance("xSeconds", seconds, localizeOptions);
184 | 
185 |     // 1 up to 60 mins
186 |   } else if (unit === "minute") {
187 |     const roundedMinutes = roundingMethod(minutes);
188 |     return locale.formatDistance("xMinutes", roundedMinutes, localizeOptions);
189 | 
190 |     // 1 up to 24 hours
191 |   } else if (unit === "hour") {
192 |     const hours = roundingMethod(minutes / 60);
193 |     return locale.formatDistance("xHours", hours, localizeOptions);
194 | 
195 |     // 1 up to 30 days
196 |   } else if (unit === "day") {
